WITH valid AS (SELECT *, INITCAP(TRIM(device_code)) AS device_code_title FROM device_readings WHERE reading_ts > TO_DATE('2025-09-01')) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, MAX(reading_ts) AS last_reading_ts, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS pressure_per_dv_04 FROM valid GROUP BY 1 HAVING ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) > 0
